package runner

// 操作清单：运行器能执行哪些操作、每个操作怎么执行，由受信任的 Python 侧通过 --ops 文件给出（语言包生成）；
// 请求里只有操作名，模型和被测代码都碰不到这张表。没有 --ops 时用 --go 生成与以前逐项相同的 Go 清单。
// The operation table: which operations the runner can execute and how. The trusted Python side supplies it through the --ops file
// (generated by a language pack); a request carries only an operation name, so neither a model nor the code under test can touch the table.
// Without --ops, --go produces the Go table identical to the previous hard-coded behaviour.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Command 是一条要执行的命令：可执行文件的绝对路径（或 {out} 占位）与参数模板。 One command: an absolute executable path (or the {out} placeholder) and an argument template.
type Command struct {
	Exe  string   `json:"exe"`
	Args []string `json:"args"`
}

// OpDef 是一个操作。 One operation.
type OpDef struct {
	Command
	// FailIfStdoutNonEmpty：例如 gofmt -l，有输出就算失败。 e.g. gofmt -l: any output is a failure.
	FailIfStdoutNonEmpty bool `json:"fail_if_stdout_nonempty"`
	// Build：先构建再运行（运行类操作）；构建产物放在临时目录，{out} 是它的路径。 Build first, then run (run-kind operations); the output goes to a temp dir and {out} is its path.
	Build *Command `json:"build,omitempty"`
	// ArgvFromRequest：运行时把请求里的 argv 原样传给程序（不经过 shell）。 Pass the request's argv to the program verbatim (never through a shell).
	ArgvFromRequest bool `json:"argv_from_request"`
	// Run：运行类操作，结果带 phase=run。 A run-kind operation: results carry phase=run.
	Run bool `json:"run"`
	// Builtin：运行器内置的操作（目前只有语法索引 go_index）。 An operation built into the runner (currently only the syntax index).
	Builtin string `json:"builtin,omitempty"`
}

// EnvPolicy 决定被测代码看到的环境变量：只有显式允许的才会传下去。 Which environment variables the code under test sees: only explicitly allowed ones are passed on.
type EnvPolicy struct {
	Allow       []string          `json:"allow"`
	Set         map[string]string `json:"set"`
	PathPrepend []string          `json:"path_prepend"`
}

// Ops 是整张表。 The whole table.
type Ops struct {
	Version    int              `json:"version"`
	RootMarker string           `json:"root_marker"`
	Env        EnvPolicy        `json:"env"`
	Operations map[string]OpDef `json:"operations"`
}

const maxOps = 32

// LoadOps 读取并校验清单；任何不合格都拒绝启动。 Read and validate the table; anything unacceptable refuses to start.
func LoadOps(path string) (*Ops, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(raw) > 1<<20 {
		return nil, fmt.Errorf("ops file too large")
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var ops Ops
	if err := dec.Decode(&ops); err != nil {
		return nil, err
	}
	if err := ops.validate(); err != nil {
		return nil, err
	}
	return &ops, nil
}

func checkCommand(name string, c Command, allowPlaceholder bool) error {
	if c.Exe == "" {
		return fmt.Errorf("%s: executable missing", name)
	}
	if !(allowPlaceholder && c.Exe == "{out}") && !filepath.IsAbs(c.Exe) {
		return fmt.Errorf("%s: executable path must be absolute", name)
	}
	if len(c.Args) > 32 {
		return fmt.Errorf("%s: too many arguments", name)
	}
	for _, a := range append([]string{c.Exe}, c.Args...) {
		if len(a) > 4096 || strings.IndexByte(a, 0) >= 0 {
			return fmt.Errorf("%s: invalid argument", name)
		}
	}
	return nil
}

func (o *Ops) validate() error {
	if o.Version != 1 {
		return fmt.Errorf("unsupported ops version")
	}
	if o.RootMarker == "" || filepath.IsAbs(o.RootMarker) || strings.Contains(o.RootMarker, "..") {
		return fmt.Errorf("invalid root marker")
	}
	if len(o.Operations) == 0 || len(o.Operations) > maxOps {
		return fmt.Errorf("operation count outside policy")
	}
	for name, op := range o.Operations {
		if name == "" || len(name) > 64 {
			return fmt.Errorf("invalid operation name")
		}
		if op.Builtin != "" {
			if op.Builtin != "go_index" {
				return fmt.Errorf("%s: unknown builtin", name)
			}
			continue
		}
		if err := checkCommand(name, op.Command, op.Build != nil); err != nil {
			return err
		}
		if op.Build != nil {
			if err := checkCommand(name+" build", *op.Build, false); err != nil {
				return err
			}
			if op.Exe != "{out}" {
				return fmt.Errorf("%s: a built operation must run {out}", name)
			}
		}
	}
	return nil
}

// Policy 是请求校验要用的两张名单。 The two lists request validation needs.
func (o *Ops) Policy() Policy {
	p := Policy{Operations: map[string]bool{}, Argv: map[string]bool{}}
	for name, op := range o.Operations {
		p.Operations[name] = true
		if op.ArgvFromRequest {
			p.Argv[name] = true
		}
	}
	return p
}

// environment 按策略构造被测代码的环境：只传允许的变量，PATH 只含清单给出的目录。 Build the environment of the code under test from the policy.
func (o *Ops) environment() []string {
	out := make([]string, 0, len(o.Env.Allow)+len(o.Env.Set)+2)
	for _, key := range o.Env.Allow {
		if val := os.Getenv(key); val != "" {
			out = append(out, key+"="+val)
		}
	}
	path := strings.Join(o.Env.PathPrepend, string(os.PathListSeparator))
	if root := os.Getenv("SystemRoot"); root != "" {
		path += string(os.PathListSeparator) + filepath.Join(root, "System32")
	}
	out = append(out, "PATH="+path)
	keys := make([]string, 0, len(o.Env.Set))
	for k := range o.Env.Set {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		out = append(out, k+"="+o.Env.Set[k])
	}
	return out
}

// LegacyGoOps 是以前写死在代码里的 Go 行为，现在表达成一张清单：--go 仍然可用，行为逐项相同。
// LegacyGoOps expresses the formerly hard-coded Go behaviour as a table, so --go keeps working with identical behaviour.
func LegacyGoOps(goExe string) *Ops {
	gofmt := filepath.Join(filepath.Dir(goExe), "gofmt"+filepath.Ext(goExe))
	return &Ops{
		Version:    1,
		RootMarker: "go.mod",
		Env: EnvPolicy{
			Allow:       []string{"SystemRoot", "WINDIR", "TEMP", "TMP", "TMPDIR", "HOME", "USERPROFILE", "LOCALAPPDATA", "GOCACHE", "GOMODCACHE", "GOPATH", "GOROOT"},
			Set:         map[string]string{"GOENV": "off", "GOWORK": "off", "GOTOOLCHAIN": "local", "CGO_ENABLED": "0", "GOPROXY": "off", "GOFLAGS": "-mod=readonly"},
			PathPrepend: []string{filepath.Dir(goExe)},
		},
		Operations: map[string]OpDef{
			"go_test":      {Command: Command{Exe: goExe, Args: []string{"test", "-json", "-count=1", "-timeout={timeout_ms}ms", "./..."}}},
			"go_vet":       {Command: Command{Exe: goExe, Args: []string{"vet", "./..."}}},
			"go_fmt_check": {Command: Command{Exe: gofmt, Args: []string{"-l", "."}}, FailIfStdoutNonEmpty: true},
			"app_run": {Command: Command{Exe: "{out}"}, Build: &Command{Exe: goExe, Args: []string{"build", "-o", "{out}", "./cmd/app"}},
				ArgvFromRequest: true, Run: true},
			"go_index": {Builtin: "go_index"},
		},
	}
}
